import{_ as e,p as l,q as a,Y as i}from"./framework-e1bed10d.js";const n={},s=i(`<h1 id="_05多表设计" tabindex="-1"><a class="header-anchor" href="#_05多表设计" aria-hidden="true">#</a> 05多表设计</h1><h2 id="表间关系" tabindex="-1"><a class="header-anchor" href="#表间关系" aria-hidden="true">#</a> 表间关系</h2><ol><li>一对多/多对一</li></ol><p>一对多主要通过外键约束来进行实现，外键约束是指一个表中的数据必须与另一个表中的数据一致，在多的一方建立外键，指向一的一方的主键</p><p>基本语法如下：</p><ul><li><p>创建表时添加外键约束：create table 表名称 (字段名称 字段类型 字段约束,... ) CONSTRAINT 外键名称 FOREIGN KEY (外键字段) REFERENCES 主表名称 (主键字段))</p></li><li><p>添加外键约束：alter table 表名称 add constraint 外键名称 foreign key (外键字段) references 主表名称 (主键字段)</p></li></ul><p>物理外键：</p><p>使用foreign key指定的外键是物理外键，使用物理外键有个以下几个缺点</p><ul><li>影响增删改的效率，每次操作都需要检查外键关系</li><li>不适用于分布式、集群的情况</li><li>容易引发数据库死锁问题，影响性能</li></ul><p>逻辑外键：</p><p>在逻辑层中，解决外键关联</p><ol start="2"><li>一对一</li></ol><p>一对一常用于对复杂单表的拆分，将一个单表拆分为多个小的表，在任意一张表中添加外键，关联另一方的主键，并设置为外键为唯一</p><ol start="3"><li>多对多</li></ol><p>多对多的实现通过建立第三张表成为中间表，中间表记录两个外键，分别对应另外两张表</p><h2 id="多表查询" tabindex="-1"><a class="header-anchor" href="#多表查询" aria-hidden="true">#</a> 多表查询</h2><p>查询多张表中的数据</p><h3 id="连接查询" tabindex="-1"><a class="header-anchor" href="#连接查询" aria-hidden="true">#</a> 连接查询</h3><ol><li>内连接查询：查询两个表的交集</li></ol><p>内连接查询有两种语法，分别是隐式内连接和显式内连接</p><ul><li><p>隐式内连接语法：select * from 表1,表2 where 表1.字段=表2.字段;</p></li><li><p>显示内连接语法：select * from 表1 [inner] join 表2 on 表1.字段=表2.字段;</p></li></ul><ol start="2"><li>左外连接查询：查询左表所有的数据，包含于右表交集的部分，语法如下：</li></ol><p>select * from 表1 left [outer] join 表2 on 表1.字段=表2.字段;</p><ol start="3"><li>右外连接查询：查询右表所有的数据，包含于左表交集的部分，语法如下：</li></ol><p>select * from 表1 right [outer] join 表2 on 表1.字段=表2.字段;</p><h3 id="联合查询" tabindex="-1"><a class="header-anchor" href="#联合查询" aria-hidden="true">#</a> 联合查询</h3><p>使用union或者union all关键字，将多次查询的结果合并起来，形成一个新的结果集</p><p>联合查询的多张表中，列数和字段类型必须保持一致</p><ol><li>union：对合并后的数据会进行去重</li></ol><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">select</span> 字段列表 <span class="token keyword">from</span> 表名 条件
<span class="token keyword">union</span>
<span class="token keyword">select</span> 字段列表 <span class="token keyword">from</span> 表名 条件
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>union all：将所有数据合并在一起</li></ol><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">select</span> 字段列表 <span class="token keyword">from</span> 表名 条件
<span class="token keyword">union</span> <span class="token keyword">all</span>
<span class="token keyword">select</span> 字段列表 <span class="token keyword">from</span> 表名 条件
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="子查询" tabindex="-1"><a class="header-anchor" href="#子查询" aria-hidden="true">#</a> 子查询</h3><ol><li>标量子查询：子查询返回的是一个单行单列的值，比如日期、数值、字符串、日期等，语法如下:</li></ol><p>select * from 表名 where 字段名 [=|!=|&gt;|&gt;=|&lt;|&lt;=] (select 字段名 from 表名 where 条件);</p><ol start="2"><li>列子查询：子查询返回的是多行单列的值，子查询的结果常用于条件满足结果值其中一个的情况，语法如下：</li></ol><p>select * from 表名 where 字段名 [in|not in] (select 字段名 from 表名 where 条件)</p><p>常用操作符：</p><ul><li>in：在指定的集合范围内，为其中一个</li><li>not in：不在指定的集合范围内，不等于其中任何一个</li><li>any、some：常与=、&gt;等比较逻辑一起使用，表示满足任意一个</li><li>all：常与=、&gt;等比较逻辑一起使用，表示满足所有</li></ul><ol start="3"><li>行子查询：子查询返回的结果是一行多列的值，子查询的结果常用于条件满足多个字段结果的情况，语法如下：</li></ol><p>select * from 表名 where (字段1,字段2...) [=|!=|in|not in] (select 字段1,字段2... from 表名 where 条件)</p><ol start="4"><li>表子查询：子查询返回的结果是一个多行多列的值，子查询的结果常用于作为一张新的表，语法如下：</li></ol><p>select e.* from (select* from 表名 where 条件) as e [inner join|left join|right join|in] 表名 on e.id=表名.id</p>`,43),r=[s];function o(t,d){return l(),a("div",null,r)}const c=e(n,[["render",o],["__file","05table-design.html.vue"]]);export{c as default};
